import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
});

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';
import './styles.css';

createRoot(document.getElementById('root')).render(<App />);

import React from 'react';

// "확인 필요"가 들어간 문장은 눈에 띄게 노란 표시
function Mark({ text }) {
  if (!text) return null;
  const parts = String(text).split(/(확인 필요)/g);
  return parts.map((p, i) =>
    p === '확인 필요' ? <mark key={i}>확인 필요</mark> : <React.Fragment key={i}>{p}</React.Fragment>
  );
}

export default function BriefView({ input, brief }) {
  const dirLabel = input.direction === 'en-ko' ? '영 → 한' : '한 → 영';
  return (
    <article className="brief">
      <header className="brief-head">
        <h2>{input.company}</h2>
        <p className="muted">
          {input.topic} · {dirLabel}
        </p>
      </header>

      <section>
        <h3>한 줄 요약</h3>
        <p className="summary"><Mark text={brief.summary} /></p>
      </section>

      <section>
        <h3>꼭 알아야 할 배경</h3>
        <ol>
          {brief.background.map((b, i) => (
            <li key={i}><Mark text={b} /></li>
          ))}
        </ol>
      </section>

      <section>
        <h3>용어집 ({brief.glossary.length})</h3>
        <table className="glossary">
          <thead>
            <tr><th>English</th><th>한국어</th><th>설명</th></tr>
          </thead>
          <tbody>
            {brief.glossary.map((g, i) => (
              <tr key={i}>
                <td>{g.en}</td>
                <td><strong>{g.ko}</strong></td>
                <td className="muted"><Mark text={g.note} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <section>
        <h3>예상 대화 흐름</h3>
        <ol className="flow">
          {brief.flow.map((f, i) => (
            <li key={i}><strong>{f.stage}</strong> — <Mark text={f.detail} /></li>
          ))}
        </ol>
      </section>

      <section>
        <h3>현장 통역 표현</h3>
        <ul className="phrases">
          {brief.phrases.map((p, i) => (
            <li key={i}>
              <span className="tag">{p.when}</span>
              <div>{p.ko}</div>
              <div className="muted">{p.en}</div>
            </li>
          ))}
        </ul>
      </section>
    </article>
  );
}

import React from 'react';
import BriefView from './BriefView.jsx';
import { sampleInput, sampleBrief } from './sampleBrief.js';

export default function App() {
  return (
    <div className="app">
      <h1>Brief Buddy</h1>
      <BriefView input={sampleInput} brief={sampleBrief} />
    </div>
  );
}

:root {
  --bg: #f7f6f3;
  --card: #ffffff;
  --text: #1f1f1f;
  --muted: #6b6b6b;
  --line: #e4e2dc;
  --accent: #2f5bd3;
  --ok: #1f8a4c;
  --bad: #c23b3b;
  font-family: -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif;
  color: var(--text);
}
body { margin: 0; background: var(--bg); }
.app { max-width: 860px; margin: 0 auto; padding: 24px 16px 64px; }
h1 { font-size: 22px; margin: 0 0 16px; }
h1 small { font-weight: 400; color: var(--muted); font-size: 14px; margin-left: 8px; }
.muted { color: var(--muted); }

/* 탭 */
.tabs { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.tabs button { background: transparent; color: var(--text); border: 1px solid var(--line); }
.tabs button.active { background: var(--text); color: #fff; border-color: var(--text); }

button {
  font: inherit; padding: 8px 14px; border-radius: 8px; border: 1px solid var(--accent);
  background: var(--accent); color: #fff; cursor: pointer;
}
button:disabled { opacity: .5; cursor: default; }
button.ghost { background: transparent; color: var(--accent); }

/* 입력 폼 */
.form { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px; display: grid; gap: 14px; }
.form label { display: grid; gap: 6px; font-weight: 600; font-size: 14px; }
.form input, .form textarea, .form select {
  font: inherit; font-weight: 400; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; width: 100%; box-sizing: border-box;
}
.form textarea { min-height: 120px; resize: vertical; }
.radio { display: flex; gap: 16px; font-weight: 400; }
.error { color: var(--bad); white-space: pre-wrap; }
.notice { background: #fff8e1; border: 1px solid #f0d77a; padding: 10px 12px; border-radius: 8px; font-size: 14px; }

/* 브리프 */
.brief { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px 24px; }
.brief-head h2 { margin: 0; }
.brief-head p { margin: 4px 0 0; }
.brief section { margin-top: 18px; }
.brief h3 { font-size: 15px; margin: 0 0 6px; border-bottom: 1px solid var(--line); padding-bottom: 4px; }
.brief ol, .brief ul { margin: 0; padding-left: 20px; }
.brief li { margin: 3px 0; line-height: 1.5; }
.summary { margin: 0; font-size: 16px; }
mark { background: #ffe58a; padding: 0 3px; border-radius: 3px; }
.glossary { width: 100%; border-collapse: collapse; font-size: 14px; }
.glossary th, .glossary td { text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--line); vertical-align: top; }
.phrases { list-style: none; padding: 0 !important; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.phrases li { border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font-size: 14px; }
.tag { display: inline-block; font-size: 11px; background: #eef2fd; color: var(--accent); padding: 1px 6px; border-radius: 4px; margin-bottom: 2px; }
.brief-actions { display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }

/* 플래시카드 */
.quiz { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px; text-align: center; }
.card {
  margin: 16px auto; max-width: 480px; min-height: 160px; border: 2px solid var(--line); border-radius: 14px;
  display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 20px; cursor: pointer;
}
.card .front { font-size: 26px; font-weight: 700; }
.card .back { margin-top: 12px; font-size: 20px; color: var(--accent); }
.card .note { margin-top: 6px; font-size: 13px; color: var(--muted); }
.quiz-buttons { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.btn-ok { background: var(--ok); border-color: var(--ok); }
.btn-bad { background: var(--bad); border-color: var(--bad); }

@media (max-width: 600px) {
  .phrases { grid-template-columns: 1fr; }
  .brief { padding: 16px; }
}

/* 인쇄: 버튼/탭 숨기고 브리프만 */
@media print {
  body { background: #fff; }
  .no-print { display: none !important; }
  .app { max-width: none; padding: 0; }
  .brief { border: none; padding: 0; }
  .brief section { break-inside: avoid; }
  .glossary { font-size: 11px; }
  .phrases li { font-size: 11px; }
  mark { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}

