// 저장은 브라우저 localStorage만 사용. (시크릿 창 등에서 막혀도 앱은 동작)
const KEY = 'brief-buddy:v1';

export function loadState() {
  try {
    return JSON.parse(localStorage.getItem(KEY)) || null;
  } catch {
    return null;
  }
}

export function saveState(state) {
  try {
    localStorage.setItem(KEY, JSON.stringify(state));
  } catch {
    // 저장 실패해도 무시
  }
}

import React from 'react';

export default function InputForm({ input, setInput, onGenerate, onSample, loading, error }) {
  const set = (k) => (e) => setInput({ ...input, [k]: e.target.value });
  const canSubmit = input.company.trim() && input.topic.trim() && !loading;

  return (
    <form
      className="form"
      onSubmit={(e) => {
        e.preventDefault();
        if (canSubmit) onGenerate();
      }}
    >
      <label>
        회사명 *
        <input value={input.company} onChange={set('company')} placeholder="예: 쿼드비 (Quad.BE)" />
      </label>
      <label>
        행사/미팅 주제 *
        <input value={input.topic} onChange={set('topic')} placeholder="예: 화장품 패키징 플랫폼 MOLDWORK 관련 미팅" />
      </label>
      <div>
        <strong style={{ fontSize: 14 }}>통역 방향</strong>
        <div className="radio">
          <label><input type="radio" checked={input.direction === 'ko-en'} onChange={() => setInput({ ...input, direction: 'ko-en' })} /> 한 → 영</label>
          <label><input type="radio" checked={input.direction === 'en-ko'} onChange={() => setInput({ ...input, direction: 'en-ko' })} /> 영 → 한</label>
        </div>
      </div>
      <label>
        참고 자료 (선택) — 회사 소개서, 아젠다, 이메일 등을 붙여넣으면 훨씬 정확해져요
        <textarea value={input.reference} onChange={set('reference')} placeholder="여기에 텍스트 붙여넣기" />
      </label>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        <button type="submit" disabled={!canSubmit}>
          {loading ? '브리프 만드는 중… (30초~1분)' : '브리프 만들기'}
        </button>
        <button type="button" className="ghost" onClick={onSample} disabled={loading}>
          샘플 브리프 보기
        </button>
      </div>
      {error && <p className="error">{error}</p>}
    </form>
  );
}

import React, { useState } from 'react';

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// 용어집 플래시카드. 틀린 카드만 다음 라운드에 다시 나온다.
export default function Practice({ glossary }) {
  const [mode, setMode] = useState('en-ko'); // en-ko: 영어 보고 한국어 / ko-en: 반대
  const [deck, setDeck] = useState(() => shuffle(glossary));
  const [idx, setIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [wrong, setWrong] = useState([]);
  const [round, setRound] = useState(1);
  const [correctTotal, setCorrectTotal] = useState(0);

  function restart(newMode = mode) {
    setMode(newMode);
    setDeck(shuffle(glossary));
    setIdx(0);
    setFlipped(false);
    setWrong([]);
    setRound(1);
    setCorrectTotal(0);
  }

  function answer(isRight) {
    const card = deck[idx];
    const nextWrong = isRight ? wrong : [...wrong, card];
    if (isRight) setCorrectTotal((n) => n + 1);
    setFlipped(false);
    if (idx + 1 < deck.length) {
      setWrong(nextWrong);
      setIdx(idx + 1);
    } else {
      // 라운드 끝: 틀린 것만 모아서 다음 라운드
      setDeck(shuffle(nextWrong));
      setWrong([]);
      setIdx(0);
      setRound((r) => r + 1);
    }
  }

  const modeButtons = (
    <div className="tabs" style={{ justifyContent: 'center' }}>
      <button className={mode === 'en-ko' ? 'active' : ''} onClick={() => restart('en-ko')}>영어 → 한국어</button>
      <button className={mode === 'ko-en' ? 'active' : ''} onClick={() => restart('ko-en')}>한국어 → 영어</button>
    </div>
  );

  if (glossary.length === 0) return <div className="quiz">용어집이 비어 있어요.</div>;

  if (deck.length === 0) {
    return (
      <div className="quiz">
        {modeButtons}
        <h2>🎉 전부 맞혔어요!</h2>
        <p className="muted">{glossary.length}개 용어 · {round - 1}라운드 만에 완료</p>
        <button onClick={() => restart()}>처음부터 다시</button>
      </div>
    );
  }

  const card = deck[idx];
  const front = mode === 'en-ko' ? card.en : card.ko;
  const back = mode === 'en-ko' ? card.ko : card.en;

  return (
    <div className="quiz">
      {modeButtons}
      <p className="muted">
        {round === 1 ? '1라운드' : `${round}라운드 (틀린 것만)`} · {idx + 1} / {deck.length}
        {' · '}맞힌 누적 {correctTotal} / {glossary.length}
      </p>
      <div className="card" onClick={() => setFlipped(true)}>
        <div className="front">{front}</div>
        {flipped ? (
          <>
            <div className="back">{back}</div>
            {card.note && <div className="note">{card.note}</div>}
          </>
        ) : (
          <div className="note">소리 내어 말해 본 뒤 카드를 눌러 정답 확인</div>
        )}
      </div>
      {flipped ? (
        <div className="quiz-buttons">
          <button className="btn-bad" onClick={() => answer(false)}>✗ 틀림</button>
          <button className="btn-ok" onClick={() => answer(true)}>✓ 맞음</button>
        </div>
      ) : (
        <button className="ghost" onClick={() => setFlipped(true)}>정답 보기</button>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import InputForm from './InputForm.jsx';
import BriefView from './BriefView.jsx';
import Practice from './Practice.jsx';
import { sampleInput, sampleBrief } from './sampleBrief.js';
import { loadState, saveState } from './storage.js';

const emptyInput = { company: '', topic: '', direction: 'ko-en', reference: '' };

export default function App() {
  const saved = loadState();
  const [tab, setTab] = useState(saved?.brief ? 'brief' : 'input');
  const [input, setInput] = useState(saved?.input || emptyInput);
  // 브리프와 함께, 그 브리프를 만든 입력값도 저장 (폼을 고쳐도 브리프 제목은 그대로)
  const [result, setResult] = useState(saved?.brief ? { input: saved.briefInput, brief: saved.brief } : null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    saveState({ input, briefInput: result?.input, brief: result?.brief });
  }, [input, result]);

  async function generate() {
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/api/brief', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || `서버 오류 (${res.status})`);
      setResult({ input: { ...input }, brief: data.brief });
      setTab('brief');
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }

  function showSample() {
    setInput(sampleInput);
    setResult({ input: sampleInput, brief: { ...sampleBrief, sample: true } });
    setTab('brief');
  }

  return (
    <div className="app">
      <h1 className="no-print">Brief Buddy <small>통역 전날 밤 20분 준비</small></h1>
      <nav className="tabs no-print">
        <button className={tab === 'input' ? 'active' : ''} onClick={() => setTab('input')}>1. 입력</button>
        <button className={tab === 'brief' ? 'active' : ''} onClick={() => setTab('brief')} disabled={!result}>2. 브리프</button>
        <button className={tab === 'practice' ? 'active' : ''} onClick={() => setTab('practice')} disabled={!result}>3. 연습</button>
      </nav>

      {tab === 'input' && (
        <InputForm input={input} setInput={setInput} onGenerate={generate} onSample={showSample} loading={loading} error={error} />
      )}

      {tab === 'brief' && result && (
        <>
          <div className="brief-actions no-print">
            <button onClick={() => window.print()}>인쇄 / PDF 저장</button>
            <button className="ghost" onClick={() => setTab('practice')}>용어 연습하기 →</button>
          </div>
          {result.brief.sample && (
            <p className="notice no-print">하드코딩된 샘플 브리프예요. 실제 생성은 "1. 입력"에서.</p>
          )}
          {result.brief.searched === false && (
            <p className="notice no-print">
              ⚠️ 웹 검색 없이 AI 지식만으로 만든 브리프예요. 회사 고유 정보(기능, 수치, 고객사)는 사실과 다를 수 있으니
              노란 "확인 필요" 외의 회사 관련 문장도 한 번씩 확인하세요. 참고 자료를 붙여넣으면 정확도가 크게 올라가요.
            </p>
          )}
          <BriefView input={result.input} brief={result.brief} />
        </>
      )}

      {tab === 'practice' && result && <Practice key={result.brief.summary} glossary={result.brief.glossary} />}
    </div>
  );
}

