3	function shuffle(arr) {
4	  const a = [...arr];
5	  for (let i = a.length - 1; i > 0; i--) {
6	    const j = Math.floor(Math.random() * (i + 1));
7	    [a[i], a[j]] = [a[j], a[i]];
8	  }
9	  return a;
10	}
11	
12	// 용어집 플래시카드. 틀린 카드만 다음 라운드에 다시 나온다.
13	export default function Practice({ glossary }) {
14	  const [mode, setMode] = useState('en-ko'); // en-ko: 영어 보고 한국어 / ko-en: 반대
15	  const [deck, setDeck] = useState(() => shuffle(glossary));
16	  const [idx, setIdx] = useState(0);
17	  const [flipped, setFlipped] = useState(false);
18	  const [wrong, setWrong] = useState([]);
19	  const [round, setRound] = useState(1);
20	  const [correctTotal, setCorrectTotal] = useState(0);
21	
22	  function restart(newMode = mode) {
23	    setMode(newMode);
24	    setDeck(shuffle(glossary));
25	    setIdx(0);
26	    setFlipped(false);
27	    setWrong([]);
28	    setRound(1);
29	    setCorrectTotal(0);
30	  }
31	
32	  function answer(isRight) {
33	    const card = deck[idx];
34	    const nextWrong = isRight ? wrong : [...wrong, card];
35	    if (isRight) setCorrectTotal((n) => n + 1);
36	    setFlipped(false);
37	    if (idx + 1 < deck.length) {
38	      setWrong(nextWrong);
39	      setIdx(idx + 1);
40	    } else {
41	      // 라운드 끝: 틀린 것만 모아서 다음 라운드
42	      setDeck(shuffle(nextWrong));
43	      setWrong([]);
44	      setIdx(0);
45	      setRound((r) => r + 1);
46	    }
47	  }
48	
49	  const modeButtons = (
50	    <div className="tabs" style={{ justifyContent: 'center' }}>
51	      <button className={mode === 'en-ko' ? 'active' : ''} onClick={() => restart('en-ko')}>영어 → 한국어</button>
52	      <button className={mode === 'ko-en' ? 'active' : ''} onClick={() => restart('ko-en')}>한국어 → 영어</button>
53	    </div>
54	  );
55	
56	  if (glossary.length === 0) return <div className="quiz">용어집이 비어 있어요.</div>;
57	
58	  if (deck.length === 0) {
59	    return (
60	      <div className="quiz">
61	        {modeButtons}
62	        <h2>🎉 전부 맞혔어요!</h2>
63	        <p className="muted">{glossary.length}개 용어 · {round - 1}라운드 만에 완료</p>
64	        <button onClick={() => restart()}>처음부터 다시</button>
65	      </div>
66	    );
67	  }
68	
69	  const card = deck[idx];
70	  const front = mode === 'en-ko' ? card.en : card.ko;
71	  const back = mode === 'en-ko' ? card.ko : card.en;
72	
73	  return (
74	    <div className="quiz">
75	      {modeButtons}
76	      <p className="muted">
77	        {round === 1 ? '1라운드' : `${round}라운드 (틀린 것만)`} · {idx + 1} / {deck.length}
78	        {' · '}맞힌 누적 {correctTotal} / {glossary.length}
79	      </p>
80	      <div className="card" onClick={() => setFlipped(true)}>
81	        <div className="front">{front}</div>
82	        {flipped ? (
83	          <>
84	            <div className="back">{back}</div>
85	            {card.note && <div className="note">{card.note}</div>}
86	          </>
87	        ) : (
88	          <div className="note">소리 내어 말해 본 뒤 카드를 눌러 정답 확인</div>
89	        )}
90	      </div>
91	      {flipped ? (
92	        <div className="quiz-buttons">
93	          <button className="btn-bad" onClick={() => answer(false)}>✗ 틀림</button>
94	          <button className="btn-ok" onClick={() => answer(true)}>✓ 맞음</button>
95	        </div>
96	      ) : (
97	        <button className="ghost" onClick={() => setFlipped(true)}>정답 보기</button>
98	      )}
99	    </div>
100	  );
101	}
