96	        try {
97	          const res = await ai.models.generateContent({
98	            model,
99	            contents: prompt,
100	            config: { responseMimeType: 'application/json', temperature: 0.3 },
101	          });
102	          return { brief: validate(extractJson(res.text || '')), sources: [], model, searched: false };
103	        } catch (e) {
104	          lastErr = e;
105	          // 키가 틀림(400/401/403) 같은 건 다른 모델로 바꿔도 안 되니 바로 중단
106	          if (e.status && e.status < 500 && e.status !== 429 && e.status !== 404) throw e;
107	          console.warn(`[brief-api] ${model} 실패 (${e.status ?? e.name}) → 다음 모델`);
108	          log('{model} 실패 → 다음 모델: {msg}', { model, msg: String(e.message).slice(0, 120) });
109	        }
110	      }
111	      throw lastErr;
112	    });
113	
