57	export function briefApiPlugin(env) {
58	  const primary = env.GEMINI_MODEL || 'gemini-3.8-flash';
59	  // 메인 모델이 과부하(5xx)·할당량(429)이면 순서대로 다른 모델로 넘어감
60	  const models = [...new Set([primary, 'gemini-3.5-flash', 'gemini-3.5-flash-lite', 'gemini-3.1-flash-lite'])];
61	  let ready = null;
62	
63	  async function setup() {
64	    // neatlogs: 해커톤 LLM 호출 기록. 키가 없으면 기록만 꺼지고 앱은 정상 동작.
65	    if (env.NEATLOGS_API_KEY) {
66	      try {
67	        await init({ apiKey: env.NEATLOGS_API_KEY, workflowName: 'brief-buddy', registerShutdownHandlers: false, debug: env.NEATLOGS_DEBUG === '1' });
68	      } catch (e) {
69	        console.warn('[neatlogs] init 실패, 기록 없이 계속:', e.message);
70	      }
71	    }
72	    // wrapGoogleGenAI: neatlogs에 프롬프트/응답/토큰 수가 LLM 호출 단위로 기록됨
73	    // timeout: 한 모델이 2분 넘게 안 답하면 포기하고 다음 모델로
74	    const ai = wrapGoogleGenAI(new GoogleGenAI({ apiKey: env.GEMINI_API_KEY, httpOptions: { timeout: 120000 } }));
75	    // 검색이 한 번 막히면(할당량 0 등) 서버를 다시 켤 때까지 검색 시도를 건너뜀
76	    let searchBlocked = false;
77	
78	    // 참고 자료 조회 (RETRIEVER)
79	    const retrieveReference = span({ kind: 'RETRIEVER', name: 'reference-retriever' }, async (ref) => {
80	      if (!ref || !ref.trim()) return null;
81	      return ref.trim();
82	    });
83	
84	    // 구글 검색 도구 호출 (TOOL)
85	    const googleSearchTool = span({ kind: 'TOOL', name: 'google-search-tool' }, async (prompt) => {
86	      const res = await ai.models.generateContent({
87	        model: primary,
88	        contents: prompt,
89	        config: { tools: [{ googleSearch: {} }], temperature: 0.3 },
90	      });
91	      const sources = (res.candidates?.[0]?.groundingMetadata?.groundingChunks || [])
92	        .map((c) => c.web)
93	        .filter(Boolean)
94	        .map((w) => ({ title: w.title, uri: w.uri }));
95	      return { res, sources };
96	    });
97	
98	    // 1차: 구글 검색으로 근거를 찾으며 생성 (지어내기 줄이기)
99	    const withSearch = span({ kind: 'TOOL', name: 'gemini-with-search' }, async (prompt) => {
100	      const { res, sources } = await googleSearchTool(prompt);
101	      return { brief: validate(extractJson(res.text || '')), sources, model: primary, searched: true };
102	    });
103	
104	    // 2차: 검색 없이 JSON 모드로 생성. 실패하면 다음 모델로.
105	    const withoutSearch = span({ kind: 'TOOL', name: 'gemini-no-search' }, async (prompt) => {
106	      let lastErr;
107	      for (const model of models) {
108	        try {
109	          const res = await ai.models.generateContent({
110	            model,
111	            contents: prompt,
112	            config: { responseMimeType: 'application/json', temperature: 0.3 },
113	          });
114	          return { brief: validate(extractJson(res.text || '')), sources: [], model, searched: false };
115	        } catch (e) {
116	          lastErr = e;
117	          // 키가 틀림(400/401/403) 같은 건 다른 모델로 바꿔도 안 되니 바로 중단
118	          if (e.status && e.status < 500 && e.status !== 429 && e.status !== 404) throw e;
119	          console.warn(`[brief-api] ${model} 실패 (${e.status ?? e.name}) → 다음 모델`);
120	          log('{model} 실패 → 다음 모델: {msg}', { model, msg: String(e.message).slice(0, 120) });
121	        }
122	      }
123	      throw lastErr;
124	    });
125	
126	    const generateBrief = span({ kind: 'WORKFLOW', name: 'generate-brief' }, async (input) => {
127	      if (input.reference) {
128	        await retrieveReference(input.reference);
129	      }
130	      const prompt = buildPrompt(input);
131	      let out = null;
132	      if (!searchBlocked) {
133	        try {
134	          out = await withSearch(prompt);
135	        } catch (e) {
136	          log('검색 생성 실패 → 검색 없이 진행: {msg}', { msg: String(e.message).slice(0, 120) });
137	          if (e.status === 429 || e.status === 403) searchBlocked = true;
138	        }
139	      }
140	      if (!out) out = await withoutSearch(prompt);
141	      const brief = out.brief;
142	      brief.sources = out.sources;
143	      brief.searched = out.searched;
144	      brief.model = out.model;
145	      return brief;
146	    });
147	    return generateBrief;
148	  }
149	
150	  return {
151	    name: 'brief-api',
152	    configureServer(server) {
153	      server.middlewares.use('/api/brief', async (req, res) => {
154	        const send = (code, obj) => {
155	          res.statusCode = code;
156	          res.setHeader('Content-Type', 'application/json; charset=utf-8');
157	          res.end(JSON.stringify(obj));
158	        };
159	        if (req.method !== 'POST') return send(405, { error: 'POST만 가능' });
160	        if (!env.GEMINI_API_KEY) {
161	          return send(500, { error: '.env 파일에 GEMINI_API_KEY가 없어요. README의 설정 방법을 봐 주세요.' });
162	        }
163	        try {
164	          let body = '';
165	          for await (const chunk of req) body += chunk;
166	          const input = JSON.parse(body || '{}');
167	          if (!input.company || !input.topic) return send(400, { error: '회사명과 주제는 꼭 입력해 주세요.' });
168	          ready ||= setup();
169	          const generateBrief = await ready;
170	          const brief = await generateBrief(input);
171	          send(200, { brief });
172	        } catch (e) {
173	          console.error('[brief-api]', e);
174	          send(500, { error: `브리프 생성 실패: ${e.message}` });
175	        }
176	      });
177	    },
178	  };
179	}
